import pennylane as qml


def bit_flip_encode_decode(logical_bit: int):
    dev = qml.device("default.qubit", wires=3, shots=None)

    @qml.qnode(dev)
    def circuit():
        if logical_bit == 1:
            qml.PauliX(wires=0)
        qml.CNOT(wires=[0, 1])
        qml.CNOT(wires=[0, 2])
        qml.CNOT(wires=[0, 2])
        qml.CNOT(wires=[0, 1])
        return qml.probs(wires=[0])

    return circuit()

